CREATE TABLE IF NOT EXISTS telemetry_core.provider_operation_fact (fact_id UUID,fact_hash FixedString(64),fact_type LowCardinality(String),source_system LowCardinality(String),source_product String,source_record_id String,source_record_hash FixedString(64),tenant_id String,project_id String,environment LowCardinality(String),primary_entity_urn String,provider_entity_urn String,task_entity_urn Nullable(String),resource_entity_urn Nullable(String),operation_name Nullable(String),occurred_at DateTime64(3,'UTC'),payload_json String,correlation_json String,source_schema_name LowCardinality(String),source_schema_version LowCardinality(String),normalizer_id LowCardinality(String),normalizer_version UInt32,projection_id LowCardinality(String),projection_version UInt32,projected_at DateTime64(3,'UTC')) ENGINE=ReplacingMergeTree(projected_at) PARTITION BY toYYYYMM(occurred_at) ORDER BY (tenant_id,project_id,primary_entity_urn,occurred_at,fact_id,projection_id,projection_version) TTL occurred_at + INTERVAL 365 DAY DELETE;
