CREATE TABLE IF NOT EXISTS telemetry_core.entity_relation_fact (relation_id UUID,relation_type LowCardinality(String),relation_version UInt32,tenant_id String,project_id String,source_entity_urn String,target_entity_urn String,source_system LowCardinality(String),target_system LowCardinality(String),valid_from DateTime64(3,'UTC'),valid_to Nullable(DateTime64(3,'UTC')),correlation_id Nullable(String),trace_id Nullable(String),causation_fact_id Nullable(UUID),route_id Nullable(String),attempt_no Nullable(UInt32),evidence_fact_ids Array(UUID),binding_source LowCardinality(String),confidence_class LowCardinality(String),created_at DateTime64(3,'UTC'),projection_id LowCardinality(String),projection_version UInt32) ENGINE=ReplacingMergeTree(created_at) PARTITION BY toYYYYMM(valid_from) ORDER BY (tenant_id,project_id,source_entity_urn,target_entity_urn,relation_type,valid_from,relation_id);
